// VERSION START: v49fd-special-board-mechanics-ownership
// Robo Rally Course Randomizer - route analysis and scoring runtime
export const ANALYZE_BUILD_ID = "v49fd-special-board-mechanics-ownership";
const ASSET_VERSION = new URL(import.meta.url).searchParams.get("v") ?? "";
const VERSION_SUFFIX = ASSET_VERSION ? `?v=${encodeURIComponent(ASSET_VERSION)}` : "";
const versionedPath = (path) => `${path}${VERSION_SUFFIX}`;

const {
  FLAG_APPROACH_WEIGHTS,
  getDamageDeckPressureMultipliers,
  getEffectiveLaserDamage,
  getFlagAreaFeatureScore,
  getHomingMissileSearchGuidanceScore,
  getTilePenaltyForFeature
} = await import(versionedPath("./feature-weights.js"));
const { getActiveVariantMentalEventRules } = await import(
  versionedPath("./variants.js")
);

// This module is a route-evaluation model for board setup, not a full RoboRally
// simulator. It resolves movement-shaping effects that materially change route
// topology and replays the board hazards that feed authoritative RE/damage
// ownership on their actual register chronology; cheap search may still use
// bounded guidance penalties for discovery.
//
// Current design invariants:
// - Every route exposed to Dev View must remain physically/register/facing exact
//   and reconstruct to a literally playable five-register program sequence.
// - Energy/upgrades remain part of route quality whenever they are in play;
//   Energy Crisis (lighterGame) is currently the only rule that removes them.
// - Programming-card legality uses only the consequential rolling window: the
//   previous five-register program plus the current one. Search carries literal
//   card-use counts for those two programs and the immediately previous executed
//   action solely so Again can repeat it; no older program history is search state.
// - Uncertainty may reduce route breadth, but it never coarsens card legality.
// - Hazards are intrinsic route costs. Traffic remains a later relational layer:
//   it never alters intrinsic legality, but confidence-weighted traffic may request
//   additional leg witnesses after the first exact route set is complete.
// - v49ej ownership invariant: completed evaluation should use RE/mechanistic
//   owners wherever a credible estimate exists. Legacy score-space/feature weights
//   may guide cheap discovery, construction, compatibility or diagnostics, but
//   should be pruned from authoritative evaluation as matching RE owners land.
// - Dynamic Archiving carries the current archive marker as per-robot exact route
//   state. It affects pit/edge/autokill consequence, exact dominance, repairs and
//   leg handoff; cheap physical discovery deliberately uses a leg-local recovery
//   proxy so archive history does not explode the estimate state/cache space.
// - Normal primary routing is estimate-first, realize-second. Every structural
//   start receives a complete physical full-course estimate, one cached leg at a
//   time, before the player-count acceptance floor is consulted. Estimated card
//   demand is soft preference only and cannot make a physical route unreachable.
// - Each complete estimate is then realized against the exact rolling two-program
//   card model. The first impossible register triggers a physical suffix replan
//   from that exact board/register/history point; a bounded estimate miss widens
//   to physical-graph exhaustion instead of becoming a hidden capacity failure.
// - Traffic uses one common start-quality scale for the whole currently
//   available field. Player-count occupancy mass is diluted across surplus starts
//   by those fixed relative qualities, then focus/known selections condition that
//   common field without recomputing the quality temperature. Route convergence
//   naturally recombines fractional occupancy later. Future traffic is then
//   attenuated continuously as elapsed registers, hazards and prior predicted
//   interactions make distant multiplayer positions less credible. Alternatives
//   are demand-led.
// - Energy is soft guidance during physical estimation and is replayed/repriced on
//   the exact realized route; it is never a physical dominance dimension.

const DIRS = {
  N: { dx: 0, dy: -1 },
  E: { dx: 1, dy: 0 },
  S: { dx: 0, dy: 1 },
  W: { dx: -1, dy: 0 }
};

const OPPOSITE = {
  N: "S",
  E: "W",
  S: "N",
  W: "E"
};

const ACTIONS = [
  { id: "WAIT", type: "wait" },
  { id: "FORWARD", type: "move", relative: "forward" },
  { id: "FORWARD_2", type: "move", relative: "forward", steps: 2 },
  { id: "FORWARD_3", type: "move", relative: "forward", steps: 3 },
  { id: "BACK", type: "move", relative: "back" },
  { id: "LEFT", type: "turn", rotation: "ccw" },
  { id: "RIGHT", type: "turn", rotation: "cw" },
  { id: "UTURN", type: "turn", rotation: "uturn" }
];

const ROTATION_ORDER = ["N", "E", "S", "W"];
const EDGE_BEHAVIOR = "pit";
const REBOOT_DAMAGE_PENALTY = 8;
const MORE_DEADLY_REBOOT_DAMAGE_PENALTY = 12;
const REGISTER_TEMPO_COST = 6.4;
const REBOOT_AVERAGE_LOST_REGISTERS = 2;
// v49bf ownership: a reboot's skipped registers are factual lost tempo.
// The former fixed +3 "discontinuity" surcharge mixed cognitive difficulty into
// route cost. Mental burden is now owned by post-build mental RE, so the legacy
// discontinuity premium remains only as an explicit zero-valued diagnostic.
const REBOOT_DISCONTINUITY_PENALTY = 0;
const REGISTER_COUNT = 5;
// Expected auto-kill exposure uses the same underlying reboot consequence for
// pits, edges, crushers and trapdoors. Recovery location then determines
// whether that threat is merely lethal, additionally loses course progress,
// or (for token-based recovery only) can sometimes be exploited as mobility.
const AUTO_KILL_SETBACK_TEMPO_PER_STEP = REGISTER_TEMPO_COST * 0.5;
const AUTO_KILL_PRESSURE_SETBACK_WEIGHT = 0.08;
const PROGRAM_CARD_COUNTS = new Map([
  ["FORWARD", 4],
  ["FORWARD_2", 3],
  ["FORWARD_3", 1],
  ["RIGHT", 4],
  ["LEFT", 4],
  ["UTURN", 1],
  ["BACK", 1],
  ["WAIT", 1]
]);
const PROGRAM_CARD_IDS = Object.freeze([...PROGRAM_CARD_COUNTS.keys()]);
const AGAIN_CARD_COUNT = 1;

// v49by PROVISIONAL card-scarcity adaptability calibration.
//
// Exact hypergeometric probability remains the mathematical model of whether a
// PARTICULAR desired program can be realized from the abstract rolling deck
// state. The scarcity normalization remains:
//
//   rawScarcityRE = max(0, P(four-copy baseline) / P(program) - 1)
//
// That definition gives exactly 0 extra RE to an ordinary four-copy baseline.
// v49by does NOT alter the hypergeometric probability or natural/Again legality.
//
// The course analyzer is not a literal deck/discard simulator, though, and it
// undervalues information/adaptation available to a real player: the player sees
// the actual hand and can often choose a different comparably good program rather
// than needing one exact preselected sequence. The rolling two-turn depletion
// state is also deliberately simplified rather than a literal deck-order model.
//
// Therefore v49by tests a SIMPLE LINEAR compression of only EXTRA scarcity:
//
//   practicalCardRE = rawScarcityRE * 0.70
//
// 0.70 is deliberately provisional, not a fitted truth. Keep this factor easy to
// inspect/remove/change. Never replace exact hypergeometry with card-category
// surcharges, and never add an independent Repeat/Again RE surcharge: repeat
// availability is already the exact union of legal natural/Again realizations.
const PROGRAM_CARD_SCARCITY_ADAPTABILITY_FACTOR = 0.70;

// v49ek programming-variant ownership. Probability mechanics and the mapping
// from probability -> practical card RE are deliberately separate.
//
// Normal play retains the provisional alpha=0.70 abstraction discount.
// Less Foreshadowing resets the programming deck at every turn boundary, so the
// previous-turn depletion state is not carried and the ordinary omitted-state
// discount is removed (base alpha=1.0). Shared Deck deliberately does NOT model
// a fictitious enlarged per-player deck or cross-robot hands; instead its omitted
// shared-state uncertainty raises alpha with player count. This increment is
// intentionally uncapped so Less Foreshadowing + Shared Deck can exceed 1.0.
// Factory Rejects changes only the actual hand size used by hypergeometry.
const SHARED_DECK_ALPHA_INCREMENT_PER_ADDITIONAL_PLAYER = 0.05;

function getProgramCardModelProfile(options = {}) {
  const playerCount = Math.max(1, Math.floor(Number(options.playerCount) || 4));
  const resetEachTurn = Boolean(options.lessForeshadowing);
  const sharedDeck = Boolean(options.classicSharedDeck);
  const sharedDeckAlphaIncrement = sharedDeck
    ? Math.max(0, playerCount - 1) * SHARED_DECK_ALPHA_INCREMENT_PER_ADDITIONAL_PLAYER
    : 0;
  const baseAlpha = resetEachTurn ? 1 : PROGRAM_CARD_SCARCITY_ADAPTABILITY_FACTOR;
  return {
    handSize: options.factoryRejects ? 7 : PROGRAM_EXACT_HAND_SIZE,
    resetEachTurn,
    previousTurnDepletionActive: !resetEachTurn,
    sharedDeck,
    playerCount,
    baseAlpha,
    sharedDeckAlphaIncrement: Number(sharedDeckAlphaIncrement.toFixed(4)),
    adaptabilityFactor: Number((baseAlpha + sharedDeckAlphaIncrement).toFixed(4)),
    sharedDeckEnlargedDeckModeled: false,
    sharedDeckCrossRobotHandsModeled: false
  };
}

function getProgramCardModelSignature(options = {}) {
  const profile = getProgramCardModelProfile(options);
  return [
    `h${profile.handSize}`,
    `reset${profile.resetEachTurn ? 1 : 0}`,
    `shared${profile.sharedDeck ? 1 : 0}`,
    `p${profile.playerCount}`,
    `a${profile.adaptabilityFactor.toFixed(4)}`
  ].join(":");
}

export function getProgramCardVariantModelSummary(options = {}) {
  const profile = getProgramCardModelProfile(options);
  return {
    model: "program-card-variant-ownership-v49ek",
    normalAdaptabilityFactor: PROGRAM_CARD_SCARCITY_ADAPTABILITY_FACTOR,
    sharedDeckAlphaIncrementPerAdditionalPlayer:
      SHARED_DECK_ALPHA_INCREMENT_PER_ADDITIONAL_PLAYER,
    handSize: profile.handSize,
    resetEachTurn: profile.resetEachTurn,
    previousTurnDepletionActive: profile.previousTurnDepletionActive,
    sharedDeck: profile.sharedDeck,
    playerCount: profile.playerCount,
    baseAlpha: profile.baseAlpha,
    sharedDeckAlphaIncrement: profile.sharedDeckAlphaIncrement,
    adaptabilityFactor: profile.adaptabilityFactor,
    sharedDeckEnlargedDeckModeled: false,
    sharedDeckCrossRobotHandsModeled: false,
    factoryRejects: Boolean(options.factoryRejects),
    lessForeshadowing: Boolean(options.lessForeshadowing),
    classicSharedDeck: Boolean(options.classicSharedDeck)
  };
}

function getProgramCardEffectivePreviousCounts(previousCounts = [], options = {}) {
  if (!getProgramCardModelProfile(options).previousTurnDepletionActive) {
    return Array(PROGRAM_CHEAP_RESOURCE_IDS.length).fill(0);
  }
  return previousCounts;
}

function getProgramCardEffectivePreviousCode(previousCode = 0, options = {}) {
  return getProgramCardModelProfile(options).previousTurnDepletionActive
    ? Math.max(0, Math.floor(Number(previousCode) || 0))
    : 0;
}

// v13/v48w card-model design invariant:
// The route analyzer is not a deck-order simulator. For planning credibility it
// uses a rolling two-turn abstraction: the previous five-register program is
// treated as known depletion from the 20-card deck, while the current program
// must fit what remains. Real reshuffle boundaries are deliberately ignored:
// they are too fragile to plan around, and modelling them would add false
// precision to a course randomizer. The four unplayed cards from the previous
// nine-card hand are not hard-depleted individually. In the exact realization
// pass their uncertainty is integrated mathematically: after the five known
// programmed cards are removed, the next nine-card hand is the marginal 9-card
// sample from the remaining 15-card population.
//
// v48x cheap programming availability alignment. Cheap search now prices the
// literal card allocation it is already carrying with a cached collapsed
// hypergeometric calculation instead of hand-tuned copy-count/combination
// surcharges. Only the card types actually required by the current program are
// enumerated; every irrelevant remaining card is collapsed into one "other"
// bucket. This keeps the hot path small while giving singleton combinations the
// same probability-shaped ordering as exact realization. The cheap proxy still
// never owns route/card legality: exact realization below unions every legal
// natural-vs-Again assignment and remains authoritative.
const PROGRAM_CHEAP_RESOURCE_IDS = Object.freeze([...PROGRAM_CARD_IDS, "AGAIN"]);
const PROGRAM_CHEAP_AVAILABILITY_CACHE = new Map();
const PROGRAM_CHEAP_AVAILABILITY_CACHE_LIMIT = 50000;
const PROGRAM_CHEAP_AVAILABILITY_TELEMETRY = {
  requests: 0,
  hits: 0,
  misses: 0,
  missComputeMs: 0
};

// v49ax: exact-within-turn union probability built from the cheap literal
// hypergeometric primitive. Natural/Again alternatives are a small union of
// monotone card-requirement events. Inclusion-exclusion is exact because the
// intersection of two such events is simply the componentwise maximum of their
// requirement vectors. This keeps the hot search on the collapsed HG cache
// rather than invoking the full hand enumerator.
const PROGRAM_CHEAP_UNION_AVAILABILITY_CACHE = new Map();
const PROGRAM_CHEAP_UNION_AVAILABILITY_CACHE_LIMIT = 50000;
const PROGRAM_CHEAP_UNION_AVAILABILITY_TELEMETRY = {
  requests: 0,
  hits: 0,
  misses: 0,
  subsetTerms: 0,
  missComputeMs: 0
};

// v49ay higher-level memo for frontier union penalties. The routing-active
// union scorer repeatedly revisits the same compact frontier state sets; cache
// that pure frontier->penalty mapping before rebuilding resource arrays and
// inclusion-exclusion cache keys. This is behavior-equivalent to v49ax.
const PROGRAM_CHEAP_FRONTIER_UNION_PENALTY_CACHE = new Map();
const PROGRAM_CHEAP_FRONTIER_UNION_PENALTY_CACHE_LIMIT = 50000;
const PROGRAM_CHEAP_FRONTIER_UNION_PENALTY_TELEMETRY = {
  requests: 0,
  hits: 0,
  misses: 0
};

// v48zb cheap Dynamic-Archiving surrogate. Exact realization still carries the
// true per-route archive marker. Physical estimate search instead anchors each
// leg at its guaranteed archive (dock / previous checkpoint) and may treat an
// archive landing that lies on a near-direct geometric path as the latest
// plausible recovery point. This keeps cheap hazard ordering recovery-aware
// without making every archive coordinate a separate hot-path search identity.
const DYNAMIC_ARCHIVE_CHEAP_PROXY_POINT_CACHE = new WeakMap();
const DYNAMIC_ARCHIVE_CHEAP_PROXY_RESULT_CACHE = new WeakMap();
const DYNAMIC_ARCHIVE_CHEAP_PROXY_CACHE_LIMIT = 50000;

// v48w exact programming availability. The exact realization pass evaluates
// the probability that a 9-card hand can supply the requested register actions
// under the rolling previous-program depletion model. The availability penalty
// is expressed in ordinary register-tempo score units. Normalizing by the chance
// of drawing at least one specified four-copy card makes that common use the
// zero-cost baseline; rarer joint requirements rise according to their actual
// inverse availability rather than a hand-tuned scarcity table.
const PROGRAM_EXACT_HAND_SIZE = 9;
const PROGRAM_EXACT_AVAILABILITY_CACHE = new Map();
const PROGRAM_EXACT_AVAILABILITY_CACHE_LIMIT = 50000;

// Nine actions are retained only as a witness window: previous complete turn
// (5) + at most four already-programmed registers of the current turn. This is
// not intended to represent the nine cards physically drawn into a hand.
const PROGRAM_HISTORY_WINDOW_SIZE = REGISTER_COUNT * 2 - 1;
const PROGRAM_RESOURCE_SUMMARY_CACHE = new Map();
const ROLLING_PROGRAM_CONTEXT_CACHE = new Map();
const ROLLING_PROGRAM_CONTEXT_CACHE_LIMIT = 50000;
// Exact transition memo keyed by canonical two-program depletion state + register
// phase + immediately previous action + candidate action. Board position is absent
// because programming-card legality does not depend on it.
const PROGRAM_ACTION_TRANSITION_CACHE = new Map();
const PROGRAM_ACTION_TRANSITION_CACHE_LIMIT = 50000;
// v17 performance: contextual dominance keys ask for the same compact rolling
// program summary at many different physical squares. Cache that *summary/key*
// separately from the hard legality allocator so key construction does not keep
// slicing the nine-action witness and recounting the same low-copy cards.
// This cache is only a memoization layer; it does not change program legality.
const ROLLING_PROGRAM_SIGNATURE_IDS = new Map();
let nextRollingProgramSignatureId = 1;

// Shared upgrade-economy defaults.  The legacy DP diagnostics and the v18
// flattened production scorer intentionally share these assumptions, while
// production no longer carries fractional upgrade-card state through routes.
export const ROUTE_ENERGY_ECONOMY_DEFAULTS = Object.freeze({
  startingEnergy: 3,
  maxEnergy: 10,
  startingUpgradeCards: 3,
  drawsPerTurn: 1,
  installsPerTurn: 1,
  drawEnergyCost: 1,
  // Unknown-card usefulness remains an expectation (default 2/3). v18 applies
  // it immediately to feature-card opportunities instead of storing card units
  // in every route-search state.
  usefulUpgradeCardRate: 2 / 3,
  // This is useful investment throughput per install opportunity, not a claim
  // that real upgrade cards cost 2E or have identical effects.
  usefulEnergyPerInstall: 2,
  powerRegistersPerEnergy: 1,
  registersPerTurn: REGISTER_COUNT
});

export function getCourseStartingEnergy(options = {}) {
  const explicitStartingEnergy = Number(options.startingEnergy);
  if (Number.isFinite(explicitStartingEnergy)) {
    return Math.max(0, Math.floor(explicitStartingEnergy));
  }
  const startingEnergyDelta = Number(options.startingEnergyDelta);
  return Math.max(
    0,
    ROUTE_ENERGY_ECONOMY_DEFAULTS.startingEnergy +
      (Number.isFinite(startingEnergyDelta) ? Math.trunc(startingEnergyDelta) : 0)
  );
}

export function getCourseStartingUpgradeCards(options = {}) {
  const explicitStartingCards = Number(options.startingUpgradeCards);
  if (Number.isFinite(explicitStartingCards)) {
    return Math.max(0, Math.floor(explicitStartingCards));
  }
  const startingCardDelta = Number(options.startingUpgradeCardDelta);
  return Math.max(
    0,
    ROUTE_ENERGY_ECONOMY_DEFAULTS.startingUpgradeCards +
      (Number.isFinite(startingCardDelta) ? Math.trunc(startingCardDelta) : 0)
  );
}

export function getCourseMaxEnergy(options = {}) {
  const explicitMaxEnergy = Number(options.maxEnergy);
  return Number.isFinite(explicitMaxEnergy)
    ? Math.max(0, Math.floor(explicitMaxEnergy))
    : ROUTE_ENERGY_ECONOMY_DEFAULTS.maxEnergy;
}

function getUpgradeEconomyRate(options, key, fallback) {
  const value = Number(options?.[key]);
  return Number.isFinite(value) ? Math.max(0, value) : fallback;
}

export function getRouteEnergyEconomyConfig(options = {}) {
  return {
    startingEnergy: getCourseStartingEnergy(options),
    maxEnergy: getCourseMaxEnergy(options),
    startingUpgradeCards: getCourseStartingUpgradeCards(options),
    drawsPerTurn: getUpgradeEconomyRate(
      options,
      "upgradeDrawsPerTurn",
      ROUTE_ENERGY_ECONOMY_DEFAULTS.drawsPerTurn
    ),
    installsPerTurn: getUpgradeEconomyRate(
      options,
      "upgradeInstallsPerTurn",
      ROUTE_ENERGY_ECONOMY_DEFAULTS.installsPerTurn
    ),
    drawEnergyCost: getUpgradeEconomyRate(
      options,
      "upgradeDrawEnergyCost",
      ROUTE_ENERGY_ECONOMY_DEFAULTS.drawEnergyCost
    ),
    usefulUpgradeCardRate: clamp(
      getUpgradeEconomyRate(
        options,
        "upgradeUsefulCardRate",
        ROUTE_ENERGY_ECONOMY_DEFAULTS.usefulUpgradeCardRate
      ),
      0,
      1
    ),
    usefulEnergyPerInstall: Math.max(1, Math.floor(getUpgradeEconomyRate(
      options,
      "upgradeUsefulEnergyPerInstall",
      ROUTE_ENERGY_ECONOMY_DEFAULTS.usefulEnergyPerInstall
    ))),
    powerRegistersPerEnergy: getUpgradeEconomyRate(
      options,
      "upgradePowerRegistersPerEnergy",
      ROUTE_ENERGY_ECONOMY_DEFAULTS.powerRegistersPerEnergy
    ),
    registersPerTurn: Math.max(1, getUpgradeEconomyRate(
      options,
      "routeRegistersPerTurn",
      ROUTE_ENERGY_ECONOMY_DEFAULTS.registersPerTurn
    ))
  };
}

// v45 production economy ----------------------------------------------------
//
// Energy and upgrade cards are tracked as separate, coupled resources. The
// route state stores useful-card units in thirds: one useful install needs 3
// units, while one unknown card contributes 2 units under the default 2/3
// usefulness assumption. This makes the coarse recurring tranche explicit:
// three normal 1E draws create about two useful cards, and two useful installs
// consume about 4E of spending capacity. The 10E cap remains only an
// instantaneous storage limit because the shadow spends Energy during future
// Upgrade Phases.
const ROUTE_USEFUL_CARD_UNIT_DENOMINATOR = 3;

function getRouteUsefulCardUnitsPerDraw(config) {
  return Math.max(
    0,
    Math.round(config.usefulUpgradeCardRate * ROUTE_USEFUL_CARD_UNIT_DENOMINATOR)
  );
}

function getRouteUsefulCardUnitsPerInstall() {
  return ROUTE_USEFUL_CARD_UNIT_DENOMINATOR;
}

function getInitialRouteUsefulCardUnits(options = {}) {
  const config = getRouteEnergyEconomyConfig(options);
  return Math.max(0, config.startingUpgradeCards * getRouteUsefulCardUnitsPerDraw(config));
}

function getRouteEconomyFullHorizonActions(options = {}) {
  const config = getRouteEnergyEconomyConfig(options);
  const turns = Math.max(0, Number(options.routeEnergyHorizonTurns) || 0);
  return Math.max(0, Math.round(turns * config.registersPerTurn));
}

function getRouteEconomyInstallExposure(boundaryAction, fullHorizonActions) {
  if (!(fullHorizonActions > 0)) return 0;
  return clamp((fullHorizonActions - boundaryAction) / fullHorizonActions, 0, 1);
}

function getRouteEconomyInstallValueR(boundaryAction, fullHorizonActions, config) {
  return (
    config.usefulEnergyPerInstall *
    config.powerRegistersPerEnergy *
    getRouteEconomyInstallExposure(boundaryAction, fullHorizonActions)
  );
}

function getRouteEconomyRemainingPhaseCount(boundaryAction, fullHorizonActions, config) {
  if (!(fullHorizonActions > boundaryAction) || !(config.registersPerTurn > 0)) return 0;
  return Math.max(0, Math.ceil((fullHorizonActions - boundaryAction) / config.registersPerTurn));
}

function clampRouteEconomyCardUnits(cardUnits, boundaryAction, fullHorizonActions, config) {
  const remainingInstalls = getRouteEconomyRemainingPhaseCount(
    boundaryAction,
    fullHorizonActions,
    config
  );
  const usefulCap = remainingInstalls * getRouteUsefulCardUnitsPerInstall();
  return Math.max(0, Math.min(Math.round(Number(cardUnits) || 0), usefulCap));
}

function getRouteEconomyPhaseChoices(energy, cardUnits, boundaryAction, fullHorizonActions, config) {
  const choices = [];
  const maxDraws = config.drawsPerTurn >= 1 ? 1 : 0;
  const maxInstalls = config.installsPerTurn >= 1 ? 1 : 0;
  const drawCardUnits = getRouteUsefulCardUnitsPerDraw(config);
  const installCardUnits = getRouteUsefulCardUnitsPerInstall();
  const maxInstallInvestment = config.usefulEnergyPerInstall;
  const installValueR = getRouteEconomyInstallValueR(
    boundaryAction,
    fullHorizonActions,
    config
  );

  for (let draw = 0; draw <= maxDraws; draw += 1) {
    const drawCost = draw * config.drawEnergyCost;
    if (drawCost > energy + 1e-9) continue;
    const energyAfterDraw = energy - drawCost;
    const cardsAfterDraw = cardUnits + draw * drawCardUnits;

    // v47.9 smooths the shared Energy shadow without changing real upgrade
    // throughput. usefulEnergyPerInstall is a coarse value/deployment budget,
    // not a literal 2E card price: a single install opportunity may therefore
    // absorb 1..N Energy of useful investment and receive the corresponding
    // fraction of its modeled value. Any positive investment still consumes
    // one useful-card opportunity and the one-install-per-turn slot.
    for (let install = 0; install <= maxInstalls; install += 1) {
      const minInvestment = install ? 1 : 0;
      const maxInvestment = install
        ? Math.min(maxInstallInvestment, Math.floor(energyAfterDraw + 1e-9))
        : 0;
      for (let investment = minInvestment; investment <= maxInvestment; investment += 1) {
        if (install && installValueR <= 1e-9) continue;
        const installCards = install * installCardUnits;
        if (installCards > cardsAfterDraw) continue;
        const valueFraction = install && maxInstallInvestment > 0
          ? investment / maxInstallInvestment
          : 0;
        choices.push({
          draw,
          install,
          installInvestment: investment,
          energyAfter: Math.max(0, energyAfterDraw - investment),
          cardUnitsAfter: Math.max(0, cardsAfterDraw - installCards),
          immediateValueR: installValueR * valueFraction,
          energySpent: drawCost + investment
        });
      }
    }
  }

  return choices;
}

function getRouteEconomyNextBoundaryAction(absoluteActionCount, config) {
  const count = Math.max(0, Math.floor(Number(absoluteActionCount) || 0));
  const phase = count % config.registersPerTurn;
  return phase === 0 ? count : count + (config.registersPerTurn - phase);
}

function buildRouteUpgradeOpportunities(
  turnsRemaining,
  initialUpgradeOpportunities,
  options = {},
  fullRouteHorizonTurns = turnsRemaining
) {
  const config = getRouteEnergyEconomyConfig(options);
  const horizon = Math.max(0, Number(turnsRemaining) || 0);
  const fullHorizon = Math.max(horizon, Number(fullRouteHorizonTurns) || 0);
  if (!(horizon > 0) || !(fullHorizon > 0) || !(config.installsPerTurn > 0)) return [];
  const initialCount = Math.max(0, Math.floor(Number(initialUpgradeOpportunities) || 0));
  const slotCount = Math.min(40, Math.ceil(horizon * config.installsPerTurn));
  const result = [];
  for (let slot = 0; slot < slotCount; slot += 1) {
    const installTime = slot / config.installsPerTurn;
    if (installTime >= horizon - 1e-9) break;
    const initial = slot < initialCount;
    let readyTime = installTime;
    if (!initial) {
      if (!(config.drawsPerTurn > 0)) continue;
      readyTime = Math.max(installTime, (slot - initialCount) / config.drawsPerTurn);
      if (readyTime >= horizon - 1e-9) continue;
    }
    result.push({
      initial,
      // Exposure is measured against the whole estimated race horizon so a
      // late install is worth less even if it is the first remaining slot.
      exposure: clamp((horizon - readyTime) / fullHorizon, 0, 1),
      acquisitionCost: initial ? 0 : config.drawEnergyCost
    });
  }
  return result;
}

export function evaluateRouteUpgradePotential(
  energy,
  turnsRemaining,
  initialUpgradeOpportunities,
  options = {},
  fullRouteHorizonTurns = turnsRemaining
) {
  const config = getRouteEnergyEconomyConfig(options);
  const reserve = clamp(Math.floor(Number(energy) || 0), 0, config.maxEnergy);
  const opportunities = buildRouteUpgradeOpportunities(
    turnsRemaining,
    initialUpgradeOpportunities,
    options,
    fullRouteHorizonTurns
  );
  let dp = Array(reserve + 1).fill(-Infinity);
  dp[0] = 0;
  opportunities.forEach((opportunity) => {
    const next = [...dp];
    for (let spent = 0; spent <= reserve; spent += 1) {
      if (!Number.isFinite(dp[spent])) continue;
      for (let investment = 1; investment <= config.usefulEnergyPerInstall; investment += 1) {
        const cost = opportunity.acquisitionCost + investment;
        if (spent + cost > reserve) break;
        const value = investment * opportunity.exposure * config.powerRegistersPerEnergy;
        next[spent + cost] = Math.max(next[spent + cost], dp[spent] + value);
      }
    }
    dp = next;
  });
  return {
    potential: Math.max(0, ...dp.filter(Number.isFinite)),
    installCapacity: opportunities.length,
    initialInstallCapacity: opportunities.filter((item) => item.initial).length,
    futureInstallCapacity: opportunities.filter((item) => !item.initial).length
  };
}

export function getRouteUpgradePotential(
  energy,
  turnsRemaining,
  initialUpgradeOpportunities,
  options = {},
  fullRouteHorizonTurns = turnsRemaining
) {
  return evaluateRouteUpgradePotential(
    energy,
    turnsRemaining,
    initialUpgradeOpportunities,
    options,
    fullRouteHorizonTurns
  ).potential;
}

export function getRouteMarginalEnergyUtility(
  energy,
  turnsRemaining,
  initialUpgradeOpportunities,
  options = {},
  fullRouteHorizonTurns = turnsRemaining
) {
  const config = getRouteEnergyEconomyConfig(options);
  const reserve = clamp(Math.floor(Number(energy) || 0), 0, config.maxEnergy);
  const current = getRouteUpgradePotential(
    reserve,
    turnsRemaining,
    initialUpgradeOpportunities,
    options,
    fullRouteHorizonTurns
  );
  return {
    plus: reserve < config.maxEnergy
      ? Math.max(0, getRouteUpgradePotential(
        reserve + 1,
        turnsRemaining,
        initialUpgradeOpportunities,
        options,
        fullRouteHorizonTurns
      ) - current)
      : 0,
    minus: reserve > 0
      ? Math.max(0, current - getRouteUpgradePotential(
        reserve - 1,
        turnsRemaining,
        initialUpgradeOpportunities,
        options,
        fullRouteHorizonTurns
      ))
      : 0
  };
}

export function getRouteEnergyGainUtility(
  energy,
  gain,
  turnsRemaining,
  initialUpgradeOpportunities,
  options = {},
  fullRouteHorizonTurns = turnsRemaining
) {
  const config = getRouteEnergyEconomyConfig(options);
  const reserve = clamp(Math.floor(Number(energy) || 0), 0, config.maxEnergy);
  const target = clamp(
    reserve + Math.max(0, Math.floor(Number(gain) || 0)),
    0,
    config.maxEnergy
  );
  if (target <= reserve) return 0;
  return Math.max(0,
    getRouteUpgradePotential(
      target,
      turnsRemaining,
      initialUpgradeOpportunities,
      options,
      fullRouteHorizonTurns
    ) -
    getRouteUpgradePotential(
      reserve,
      turnsRemaining,
      initialUpgradeOpportunities,
      options,
      fullRouteHorizonTurns
    )
  );
}

export function estimateInitialUpgradeOpportunitiesRemaining(
  elapsedTurns,
  horizonTurns,
  config
) {
  if (!(horizonTurns > 0) || !(config.startingUpgradeCards > 0)) return 0;
  const remainingTurns = Math.max(0, horizonTurns - elapsedTurns);
  const exposureFraction = clamp(remainingTurns / horizonTurns, 0, 1);
  const routeScaledHand = Math.round(config.startingUpgradeCards * exposureFraction);
  const remainingInstallCapacity = Math.max(
    0,
    Math.ceil(remainingTurns * config.installsPerTurn)
  );
  // This is deliberately a neutral opportunity proxy, not a claim about which
  // unknown starting cards the player actually installed or saved.
  return Math.min(
    config.startingUpgradeCards,
    routeScaledHand,
    remainingInstallCapacity
  );
}
const ROUTE_PATH_KEY_CACHE = new WeakMap();
const ROUTE_TILE_SET_CACHE = new WeakMap();
const ROUTE_EDGE_SET_CACHE = new WeakMap();
const ROUTE_DIRECTIONS_CACHE = new WeakMap();
const TRAFFIC_TIMELINE_CACHE = new WeakMap();
const TRAFFIC_PAIR_PROFILE_CACHE = new WeakMap();
const TRAFFIC_DISPLACEMENT_CACHE = new WeakMap();
const TRAFFIC_CONTROL_SEVERITY_CACHE = new WeakMap();

const CONTEXTUAL_PHYSICAL_TRANSITION_CACHE = new WeakMap();
const CONTEXTUAL_PHYSICAL_TRANSITION_CACHE_LIMIT = 50000;
// v48zv: wall/red-wall/green-wall blocking across a directed adjacent boundary
// is pure board geometry. Pressure scoring and actual movement ask the same
// question repeatedly on physical-cache misses, so memoize that board-local
// boolean per tileMap without putting goal/recovery/register state into the key.
const BOUNDARY_WALL_BLOCK_CACHE = new WeakMap();
// Recovery-aware pit/edge exposure is derived once when a physical template is
// cached. Ordinary cache hits can then bypass all recovery/proxy work entirely.
const CONTEXTUAL_RECOVERY_PRESSURE_POINT_CACHE = new WeakMap();

function getContextualPhysicalOptionSignature(options = {}) {
  const physicalTemplateOnly = Boolean(options.contextualPhysicalTemplateOnly);
  const rebootTokens = physicalTemplateOnly
    ? ""
    : (options.rebootTokens || [])
      .map((token) => [
        token.x ?? "",
        token.y ?? "",
        token.facing ?? token.dir ?? "",
        token.boardId ?? token.board ?? ""
      ].join(","))
      .sort()
      .join(";");

  const boardRects = physicalTemplateOnly
    ? ""
    : (options.boardRects || [])
      .map((rect) => [
        rect.id ?? rect.boardId ?? "",
        rect.x ?? "",
        rect.y ?? "",
        rect.width ?? rect.w ?? "",
        rect.height ?? rect.h ?? ""
      ].join(","))
      .sort()
      .join(";");

  const cheapArchiveOrigin = options.contextualCheapDynamicArchiveOrigin;

  return [
    physicalTemplateOnly ? "physical-template" : (options.recoveryRule ?? ""),
    !physicalTemplateOnly && options.contextualCheapDynamicArchiveApproximation
      ? `cheapArchiveOrigin=${cheapArchiveOrigin?.x ?? "?"},${cheapArchiveOrigin?.y ?? "?"}`
      : "",
    options.lessDeadlyGame ? 1 : 0,
    options.repulsorOverdrive ? 1 : 0,
    options.repairStations ? 1 : 0,
    options.lighterGame ? 1 : 0,
    options.routeAwareBatteryScoring ? 1 : 0,
    options.flamingOil ? 1 : 0,
    options.playerCount ?? "",
    rebootTokens,
    boardRects
  ].join("|");
}

function getContextualPhysicalTransitionCache(tileMap) {
  let cache = CONTEXTUAL_PHYSICAL_TRANSITION_CACHE.get(tileMap);
  if (!cache) {
    cache = new Map();
    CONTEXTUAL_PHYSICAL_TRANSITION_CACHE.set(tileMap, cache);
  }
  return cache;
}

function cloneCachedTransition(transition) {
  if (!transition) return transition;
  return {
    ...transition,
    from: transition.from ? { ...transition.from } : transition.from,
    to: transition.to ? { ...transition.to } : transition.to,
    rebootChoices: transition.rebootChoices
      ? transition.rebootChoices.map((choice) => ({ ...choice }))
      : transition.rebootChoices,
    traversed: (transition.traversed || []).map((point) => ({ ...point })),
    conveyorSteps: (transition.conveyorSteps || []).map((step) => ({
      ...step,
      from: step.from ? { ...step.from } : step.from,
      to: step.to ? { ...step.to } : step.to
    })),
    boardEvents: (transition.boardEvents || []).map((event) => ({
      ...event,
      from: event.from ? { ...event.from } : event.from,
      to: event.to ? { ...event.to } : event.to,
      at: event.at ? { ...event.at } : event.at
    })),
    pendingReboot: transition.pendingReboot
      ? {
        ...transition.pendingReboot,
        state: transition.pendingReboot.state ? { ...transition.pendingReboot.state } : null,
        crashPoint: transition.pendingReboot.crashPoint ? { ...transition.pendingReboot.crashPoint } : null
      }
      : null
  };
}

function getCachedContextualPhysicalTransition(
  tileMap,
  state,
  action,
  options,
  optionSignature
) {
  const physicalTemplateOnly = Boolean(options.contextualPhysicalTemplateOnly);
  const goal = options.goal;
  const physicalMissProfile =
    options.contextualPhysicalMissProfile &&
    typeof options.contextualPhysicalMissProfile === "object"
      ? options.contextualPhysicalMissProfile
      : null;
  const lookupStartedAt = physicalMissProfile ? analysisTelemetryNow() : 0;
  const key = [
    state.x,
    state.y,
    state.facing,
    action.id,
    Number.isInteger(options.registerIndex)
      ? `r${((options.registerIndex % REGISTER_COUNT) + REGISTER_COUNT) % REGISTER_COUNT}`
      : "r?",
    // v48zd: cheap/exact contextual route searches share a pure movement
    // template. Goal and recovery context are applied after the cached board
    // mechanics are known, so they must not fragment the physical cache.
    physicalTemplateOnly ? "goal-" : (goal?.x ?? ""),
    physicalTemplateOnly ? "goal-" : (goal?.y ?? ""),
    physicalTemplateOnly
      ? "archive-"
      : options.recoveryRule === "dynamic_archiving" &&
        !options.contextualCheapDynamicArchiveApproximation
        ? `archive${options.dynamicArchivePoint?.x ?? "?"},${options.dynamicArchivePoint?.y ?? "?"}`
        : "archive-",
    physicalTemplateOnly
      ? "dockStart-"
      : options.recoveryRule === "reboot_tokens" &&
        !getBoardRectForPoint(state, options.boardRects)
        ? `dockStart${options.rebootStart?.x ?? "?"},${options.rebootStart?.y ?? "?"}`
        : "dockStart-",
    optionSignature
  ].join("|");

  const cache = getContextualPhysicalTransitionCache(tileMap);
  const dynamicArchiveTelemetry = options.recoveryRule === "dynamic_archiving";
  if (dynamicArchiveTelemetry) {
    DYNAMIC_ARCHIVE_CACHE_TELEMETRY.requests += 1;
    if (!physicalTemplateOnly && !options.contextualCheapDynamicArchiveApproximation) {
      DYNAMIC_ARCHIVE_CACHE_TELEMETRY.archivePoints.add(
        `${options.dynamicArchivePoint?.x ?? "?"},${options.dynamicArchivePoint?.y ?? "?"}`
      );
    }
  }
  const cached = cache.get(key);
  if (cached) {
    if (dynamicArchiveTelemetry) DYNAMIC_ARCHIVE_CACHE_TELEMETRY.hits += 1;
    return {
      transition: physicalTemplateOnly
        ? finalizeContextualPhysicalTransition(tileMap, cached, options)
        : cached,
      hit: true
    };
  }

  if (physicalMissProfile) {
    physicalMissProfile.physicalMissSampledCalls += 1;
    physicalMissProfile.physicalMissLookupMs += analysisTelemetryNow() - lookupStartedAt;
  }
  if (dynamicArchiveTelemetry) DYNAMIC_ARCHIVE_CACHE_TELEMETRY.misses += 1;
  const simulationOptions = physicalTemplateOnly
    ? {
      ...options,
      goal: null,
      dynamicArchivePoint: null,
      contextualDeferRebootRecovery: true,
      contextualSkipRecoveryAwarePressure: true
    }
    : options;

  const transition = simulateAction(tileMap, state, action, simulationOptions);

  let phaseStartedAt = physicalMissProfile ? analysisTelemetryNow() : 0;
  const cachedTransition = cloneCachedTransition(transition);
  if (physicalMissProfile) {
    physicalMissProfile.physicalMissCloneMs += analysisTelemetryNow() - phaseStartedAt;
  }

  if (physicalTemplateOnly) {
    phaseStartedAt = physicalMissProfile ? analysisTelemetryNow() : 0;
    CONTEXTUAL_RECOVERY_PRESSURE_POINT_CACHE.set(
      cachedTransition,
      collectContextualRecoveryPressurePoints(tileMap, cachedTransition, options)
    );
    if (physicalMissProfile) {
      physicalMissProfile.physicalMissRecoveryPressureMs +=
        analysisTelemetryNow() - phaseStartedAt;
    }
  }

  phaseStartedAt = physicalMissProfile ? analysisTelemetryNow() : 0;
  cache.set(key, cachedTransition);
  if (cache.size > CONTEXTUAL_PHYSICAL_TRANSITION_CACHE_LIMIT) {
    const oldestKey = cache.keys().next().value;
    if (oldestKey !== undefined) {
      cache.delete(oldestKey);
    }
  }
  if (physicalMissProfile) {
    physicalMissProfile.physicalMissCacheStoreMs += analysisTelemetryNow() - phaseStartedAt;
  }

  phaseStartedAt = physicalMissProfile ? analysisTelemetryNow() : 0;
  const finalizedTransition = physicalTemplateOnly
    ? finalizeContextualPhysicalTransition(tileMap, cachedTransition, options)
    : transition;
  if (physicalMissProfile) {
    physicalMissProfile.physicalMissFinalizeMs += analysisTelemetryNow() - phaseStartedAt;
  }

  return {
    transition: finalizedTransition,
    hit: false
  };
}

